import six
import copy
from functools import wraps
from taf.analyzer.iperf_throughput.cell import DataCell, JitterCell, BandwidthCell, BitrateCell


def clone_empty(entry):
    if hasattr(entry, '__clone__empty'):
        return entry.__clone__empty()

    if isinstance(entry, six.string_types):
        return ''

    if isinstance(entry, six.integer_types):
        return 0

    if isinstance(entry, float):
        return 0.0


class Entry(object):
    def __init__(self):
        self._cells = []
        self.header = None

    def add_cell(self, cell):
        if cell:
            self._cells.append(cell)
            setattr(self, cell.name(), cell)

    @property
    def cells(self):
        return self._cells

    def __clone__empty(self):
        cloned = copy.deepcopy(self)
        for cell in self._cells:
            value = getattr(cloned, cell.name())
            if issubclass(value.__class__, DataCell):
                value.empty()
        return cloned


class RawEntry(Entry):
    def __init__(self, raw):
        super(RawEntry, self).__init__()
        self._raw = raw

    @property
    def raw(self):
        return self._raw


class OperableEntry(Entry):

    def __init__(self, entry):
        super(OperableEntry, self).__init__()
        for cell in entry.cells:
            self.add_cell(cell)
        self.header = entry.header

    def __add__(self, rhs):
        copy_obj = copy.copy(self)
        for cell in self.cells:
            cell_name = cell.name()
            if not hasattr(rhs, cell_name):
                continue
            value = getattr(copy_obj, cell_name)
            if not issubclass(value.__class__, DataCell):
                continue
            additional_value = getattr(rhs, cell_name)
            if cell.unit and '/sec' in cell.unit:
                final_value = ((value * self.interval_value + additional_value * rhs.interval_value)
                               / (self.interval_value + rhs.interval_value))
            else:
                final_value = value + additional_value
            setattr(copy_obj, cell_name, final_value)
        return copy_obj

    @property
    def interval_value(self):
        return self.interval.interval_end - self.interval.interval_start

    def __mul__(self, rhs):
        # rhs should be integer or float
        times = rhs
        copy_obj = copy.copy(self)
        for cell in self.cells:
            value = getattr(copy_obj, cell.name())
            if issubclass(value.__class__, DataCell):
                setattr(copy_obj, cell.name(), value * times)
        return copy_obj

    def _div(self, other):
        # rhs should be integer or float
        times = other
        copy_obj = copy.copy(self)
        for cell in self.cells:
            value = getattr(copy_obj, cell.name())
            if issubclass(value.__class__, DataCell):
                setattr(copy_obj, cell.name(), value / times)
        return copy_obj

    def __div__(self, other):
        return self._div(other)

    def __truediv__(self, other):
        return self._div(other)

    def to_dict(self):
        return {cell.name(): getattr(self, cell.name()).to_dict()
                for cell in self.cells
                if issubclass(getattr(self, cell.name()).__class__, DataCell)}


class keycell(object):
    """
    key cell decorator
    """
    def __init__(self, name=None):
        self.name = name

    def __call__(self, cls):
        return self._decorate(cls)

    def decorate(self, cls):
        return self._decorate(cls)

    def _decorate(self, cls):  # noqa: C901
        name = self.name
        if not issubclass(cls, OperableEntry):
            raise AttributeError("keycell only can decorate subclass of OperableEntry")

        def decorate_with_key_cell_existing(func):
            @wraps(func)
            def decorated(*args, **kwargs):
                func(*args, **kwargs)
                if not hasattr(args[0], self.name):
                    raise AttributeError("object of '{}' must have attribute '{}'".format(cls.__name__, self.name))

            return decorated

        def _less_than(own, other):
            if other is None:
                return True
            return getattr(own, name) < getattr(other, name)

        def _greater_than(own, other):
            if other is None:
                return True
            return getattr(own, name) > getattr(other, name)

        def to_dict(own):
            return getattr(own, name).to_dict()

        def get_key_cell(own):
            return getattr(own, name)

        def is_per_sec_value(own):
            return '/sec' in getattr(own, name).unit

        def value(own):
            return getattr(own, name).value

        if name:
            setattr(cls, '__init__', decorate_with_key_cell_existing(cls.__init__))
            setattr(cls, '__lt__', _less_than)
            setattr(cls, '__gt__', _greater_than)
            setattr(cls, 'to_dict', to_dict)
            setattr(cls, 'get_key_cell', get_key_cell)
            setattr(cls, 'is_per_sec_value', is_per_sec_value)
            setattr(cls, 'value', value)
        return cls


class Iperf2SingleThreadClientClientSideConclusionEntry(OperableEntry):
    def __sub__(self, rhs):
        copy_obj = copy.copy(self)
        bandwidth_accumulation = self.bandwidth * self.interval_value
        for cell in self.cells:
            cell_name = cell.name()
            if cell_name == BandwidthCell.name():
                value = ((bandwidth_accumulation - rhs.bandwidth * rhs.interval_value)
                         / (self.interval_value - rhs.interval_value))
            else:
                later_value = getattr(rhs, cell_name)
                if not issubclass(later_value.__class__, DataCell):
                    continue
                value = getattr(copy_obj, cell_name) - later_value

            setattr(copy_obj, cell_name, value)
        return copy_obj


class Iperf2SingleThreadClientServerSideConclusionEntry(OperableEntry):
    def __sub__(self, rhs):
        copy_obj = copy.copy(self)
        bandwidth_accumulation = self.bandwidth * self.interval_value

        value = None
        for cell in self.cells:
            cell_name = cell.name()
            if cell_name == BandwidthCell.name():
                value = ((bandwidth_accumulation - rhs.bandwidth * rhs.interval_value)
                         / (self.interval_value - rhs.interval_value))
            elif cell_name == JitterCell.name():
                jitter_accumulation = self.jitter * self.interval_value
                value = jitter_accumulation - rhs.jitter
            else:
                later_value = getattr(rhs, cell_name)
                if not issubclass(later_value.__class__, DataCell):
                    continue
                value = getattr(copy_obj, cell_name) - later_value

            setattr(copy_obj, cell_name, value)
        return copy_obj


class Iperf3SingleThreadClientClientSideConclusionEntry(OperableEntry):
    def __sub__(self, rhs):
        copy_obj = copy.copy(self)

        for cell in self.cells:
            cell_name = cell.name()
            if cell_name == BandwidthCell.name():
                bandwidth_accumulation = self.bandwidth * self.interval_value
                value = ((bandwidth_accumulation - rhs.bandwidth * rhs.interval_value)
                         / (self.interval_value - rhs.interval_value))
            elif cell_name == BandwidthCell.name():
                bitrate_accumulation = self.bitrate * self.interval_value
                value = ((bitrate_accumulation - rhs.bitrate * rhs.interval_value)
                         / (self.interval_value - rhs.interval_value))
            else:
                later_value = getattr(rhs, cell_name)
                if not issubclass(later_value.__class__, DataCell):
                    continue
                value = getattr(copy_obj, cell_name) - later_value

            setattr(copy_obj, cell_name, value)
