class ComparableEntryFactory(object):

    def __init__(self, key_cell_name, entry_class):
        self._entry_class = type('new_item_cls', (entry_class,), {})
        keycell_instance = keycell(key_cell_name)
        self._new_entry_class = keycell_instance.decorate(self._entry_class)

    def create(self, entry):
        return self._new_entry_class(entry)
